window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7ec975129ec8f170"]={"versions": [{"id": "FIG-7ec975129ec8f170", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Kompositionsdiagramm (Software Composition Diagram / VFB Architectural View) gemäß dem AUTOSAR-Softwarekomponenten-Metamodell (<code>CompositionSwComponentType</code>).\n</li><li><strong>Technischer Zweck:</strong> Definition der logischen Software-Architektur und Domain-Dekomposition der Domäne <em>Chassis</em> (Fahrwerk), speziell der Sub-Komposition <em>Suspension</em> (Federung/Dämpfung/Niveauregelung), sowie deren VFB-Kopplung an die Nachbardomänen <em>Power Train</em> und <em>Body</em>.\n</li><li><strong>Release-Hinweis:</strong> In den Releases R3.0.7 und R3.1.5 weist das Spezifikationsdokument einen Render-/Exportfehler auf (Text-Layer der Blöcke ist im Vektor-Asset unvollständig/leer). Die strukturelle Identität und Nomenklatur ist mit dem korrigierten Folgerelease R3.2.3 (<code>FIG-9251c4ccddafefc8</code>) synchronisiert.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Domänen-Container &amp; Software-Kompositionen</h5>\n<ul class=\"fig-list\"><li><strong>Chassis (Root Composition / Domain):</strong>\n<ul class=\"fig-list\"><li>Beherbergt übergeordnete Fahrdynamik- und Stabilitätsfunktionen:\n<ul class=\"fig-list\"><li><code>Electronic Stability Control (ESC)</code>: Querdynamik-, Giermoment- und Radschlupfregelung.\n</li><li><code>Roll Stability Control (RSC)</code>: Erkennung und aktive Vermeidung von Fahrzeug-Überschlägen (dynamische Wankmomentenverteilung).\n</li></ul>\n</li><li>Enthält die hierarchisch eingebettete Sub-Komposition <code>Active Suspension</code>.\n</li></ul>\n</li><li><strong>Active Suspension (Sub-Composition):</strong>\n<ul class=\"fig-list\"><li>Kapselt alle mechatronischen Vertikal- und Aufbau-Dynamikfunktionen. Enthält folgende atomare Software-Components (<code>ApplicationSwComponentType</code> / <code>SensorActuatorSwComponentType</code>):\n<ul class=\"fig-list\"><li><code>Semi-active Damper</code>: Kennfeld- und kontinuierliche Ventilverstellung adaptiver Dämpfer.\n</li><li><code>Switchable Damper</code>: Diskrete Dämpferhärte-Umschaltung (z. B. Komfort / Sport).\n</li><li><code>Active Stabilizer</code>: Aktive Wankstabilisierung (z. B. elektromechanischer Wankstabilisator / Schwenkmotor).\n</li><li><code>Switchable Damper</code> (weitere Instanz / achsspezifische Ausprägung).\n</li><li><code>Switchable Spring</code>: Steifigkeits- und Federratenumschaltung (z. B. Schalten von Luftfedervolumina).\n</li><li><code>Body Level Actuator</code>: Aktive Niveauregulierung / Höhenstandsverstellung.\n</li><li><code>Full Active Suspension</code>: Vollaktives Fahrwerkssystem mit direkter fahrbahn- und zustandsabhängiger Krafteinprägung zwischen Rad und Aufbau.\n</li><li><code>Active Camber</code>: Aktive Radsturzeinstellung zur Optimierung der Reifenkontaktfläche und Querkraftübertragung.\n</li></ul>\n</li></ul>\n</li><li><strong>Power Train (Domain Composition):</strong>\n<ul class=\"fig-list\"><li>Beherbergt den <code>Power Train Coordinator</code>: Schnittstelle für Längsdynamik- und Drehmomentenkoordination (Antriebsmomenten-Anforderung und -Reduktion).\n</li></ul>\n</li><li><strong>Body (Domain Composition):</strong>\n<ul class=\"fig-list\"><li>Karosserie- und Komfortelektronik (Lieferant für Karosseriezustände, Tür-/Klappenstatus, Bedienerschnittstellen für Niveauwahl).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Bus-Topologie &amp; Port-Verbindungen</h5>\n<ul class=\"fig-list\"><li><strong>VFB-Interconnect:</strong> Horizontale Leitungsstränge repräsentieren den logischen <em>Virtual Functional Bus</em> (VFB).\n</li><li><strong>Konnektoren:</strong>\n<ul class=\"fig-list\"><li><em>Assembly Connectors</em> (<code>AssemblySwConnector</code>): Verbinden Ports gleichrangiger SW-Cs innerhalb der Domänen bzw. über Domänengrenzen hinweg.\n</li><li><em>Delegation Connectors</em> (<code>DelegationSwConnector</code>): Führen interne Ports der Sub-Komposition <code>Active Suspension</code> über Kompositionsgrenzen an den VFB-Bus der übergeordneten Domäne <code>Chassis</code>.\n</li></ul>\n</li><li><strong>Interface-Typen:</strong> Überwiegend <code>SenderReceiverInterface</code> (periodische Zustandsgrößen, Soll-/Ist-Kräfte, Höhenstände) sowie <code>ClientServerInterface</code> (Zustandsumschaltung, Funktionsfreigaben, Kalibrierung).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Triggerung &amp; Task-Scheduling:</strong>\n<ul class=\"fig-list\"><li>Periodische Ausführung über RTE-Events (<code>TimingEvent</code>):\n<ul class=\"fig-list\"><li>Stabilitätskritische Regelschleifen (<code>ESC</code>, <code>RSC</code>, <code>Active Stabilizer</code>, <code>Full Active Suspension</code>): Typische Abtastzeiten von <strong>5 ms bis 10 ms</strong>.\n</li><li>Niveau- und Komfortregelung (<code>Body Level Actuator</code>, <code>Switchable Spring</code>): Typische Abtastzeiten von <strong>20 ms bis 100 ms</strong>.\n</li></ul>\n</li></ul>\n</li><li><strong>Datenfluss &amp; Regelkreis:</strong>\n<ol class=\"fig-list\"><li><em>Eingangsgrößen:</em> Rechnerische Erfassung von Raddrehzahlen, Lenkwinkel, Gierrate, Quer-/Längsbeschleunigung und Federwegen/Höhenständen über Sensor-SW-Cs.\n</li><li><em>Koordination:</em> <code>ESC</code> und <code>RSC</code> ermitteln fahrdynamische Momentenbedarfe; Koordination mit dem <code>Power Train Coordinator</code> zur Begrenzung/Erhöhung des Antriebsmoments via VFB.\n</li><li><em>Aktuator-Sollwertgenerierung:</em> <code>Active Suspension</code> transformiert Wank-, Nick- und Hubanforderungen in rad- bzw. achsspezifische Sollwerte für Dämpfer-, Feder-, Stabilisator- und Sturzaktoren.\n</li><li><em>Ausgangsgrößen:</em> Übertragung an Aktuator-SW-Cs oder unterlagerte Leistungstreiber.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Plausibilisierungsfehler (z. B. Sensor-Ausfall, Signal-Ungültigkeiten <code>INVALID</code>): Asynchrone Fehlermeldung an den Diagnostic Event Manager (<code>Dem_SetEventStatus</code>).\n</li><li>Rückfallebenen: Bei Teilausfall Umschaltung der adaptiven/aktiven Aktuatoren in den fail-safe passiven Zustand (z. B. Dämpfer auf Default-Kennlinie).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierte Applikationsschnittstellen (AUTOSAR AI):</strong>\n<ul class=\"fig-list\"><li>Die in <code>AUTOSAR_ApplicationInterfaces_Explanation_Chassis</code> spezifizierten Komponenten erfordern zwingend die Einhaltung der standardisierten Datentypen, Einheiten (SI-Basiseinheiten wie m, m/s^2, rad/s, N, Nm), Skalierungen und Invalid-Werte gemäß den entsprechenden <code>PortInterface</code>-Definitionen.\n</li></ul>\n</li><li><strong>Topologie- und ECU-Allokation:</strong>\n<ul class=\"fig-list\"><li>Die gezeigte VFB-Struktur ist hardware-agnostisch. Die SW-Cs können auf einem zentralen Domain-Controller (Chassis/Fahrwerk-ECU) konsolidiert oder über mehrere vernetzte Steuergeräte (z. B. ESC-Steuergerät, Dämpfer-ECUs via CAN/FlexRay/Ethernet) verteilt werden.\n</li><li>Bei verteilter Allokation mappt der Systemintegrator die VFB-Verbindungen auf Signal-Frames im COM-Stack (<code>ComSignal</code>, <code>PDU</code>).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen (Embedded):</strong>\n<ul class=\"fig-list\"><li>Aktive Dämpfer- und Krafteinprägungssysteme (<code>Full Active Suspension</code>, <code>Semi-active Damper</code>) weisen extrem enge Latenztoleranzen auf.\n</li><li>Falls die standardmäßige RTE-Kommunikation bei hochfrequenten PWM-/SPI-Treiberansteuerungen zu hohe Laufzeit-Overheads erzeugt, erfolgt die unterlagerte Aktuatoranbindung normativ über ein <em>Complex Device Driver</em> (CDD) unter Umgehung des Standard-I/O-Stacks.\n</li></ul>\n</li></ul>"}, {"id": "FIG-9251c4ccddafefc8", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Kompositionsdiagramm (Software Composition Diagram / VFB Architectural View) gemäß dem AUTOSAR-Softwarekomponenten-Metamodell (<code>CompositionSwComponentType</code>).\n</li><li><strong>Technischer Zweck:</strong> Definition der logischen Software-Architektur und Domain-Dekomposition der Domäne <em>Chassis</em> (Fahrwerk), speziell der Sub-Komposition <em>Suspension</em> (Federung/Dämpfung/Niveauregelung), sowie deren VFB-Kopplung an die Nachbardomänen <em>Power Train</em> und <em>Body</em>.\n</li><li><strong>Release-Hinweis:</strong> In den Releases R3.0.7 und R3.1.5 weist das Spezifikationsdokument einen Render-/Exportfehler auf (Text-Layer der Blöcke ist im Vektor-Asset unvollständig/leer). Die strukturelle Identität und Nomenklatur ist mit dem korrigierten Folgerelease R3.2.3 (<code>FIG-9251c4ccddafefc8</code>) synchronisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Domänen-Container &amp; Software-Kompositionen</h5>\n<ul class=\"fig-list\"><li><strong>Chassis (Root Composition / Domain):</strong>\n<ul class=\"fig-list\"><li>Beherbergt übergeordnete Fahrdynamik- und Stabilitätsfunktionen:\n<ul class=\"fig-list\"><li><code>Electronic Stability Control (ESC)</code>: Querdynamik-, Giermoment- und Radschlupfregelung.\n</li><li><code>Roll Stability Control (RSC)</code>: Erkennung und aktive Vermeidung von Fahrzeug-Überschlägen (dynamische Wankmomentenverteilung).\n</li></ul>\n</li><li>Enthält die hierarchisch eingebettete Sub-Komposition <code>Active Suspension</code>.\n</li></ul>\n</li><li><strong>Active Suspension (Sub-Composition):</strong>\n<ul class=\"fig-list\"><li>Kapselt alle mechatronischen Vertikal- und Aufbau-Dynamikfunktionen. Enthält folgende atomare Software-Components (<code>ApplicationSwComponentType</code> / <code>SensorActuatorSwComponentType</code>):\n<ul class=\"fig-list\"><li><code>Semi-active Damper</code>: Kennfeld- und kontinuierliche Ventilverstellung adaptiver Dämpfer.\n</li><li><code>Switchable Damper</code>: Diskrete Dämpferhärte-Umschaltung (z. B. Komfort / Sport).\n</li><li><code>Active Stabilizer</code>: Aktive Wankstabilisierung (z. B. elektromechanischer Wankstabilisator / Schwenkmotor).\n</li><li><code>Switchable Damper</code> (weitere Instanz / achsspezifische Ausprägung).\n</li><li><code>Switchable Spring</code>: Steifigkeits- und Federratenumschaltung (z. B. Schalten von Luftfedervolumina).\n</li><li><code>Body Level Actuator</code>: Aktive Niveauregulierung / Höhenstandsverstellung.\n</li><li><code>Full Active Suspension</code>: Vollaktives Fahrwerkssystem mit direkter fahrbahn- und zustandsabhängiger Krafteinprägung zwischen Rad und Aufbau.\n</li><li><code>Active Camber</code>: Aktive Radsturzeinstellung zur Optimierung der Reifenkontaktfläche und Querkraftübertragung.\n</li></ul>\n</li></ul>\n</li><li><strong>Power Train (Domain Composition):</strong>\n<ul class=\"fig-list\"><li>Beherbergt den <code>Power Train Coordinator</code>: Schnittstelle für Längsdynamik- und Drehmomentenkoordination (Antriebsmomenten-Anforderung und -Reduktion).\n</li></ul>\n</li><li><strong>Body (Domain Composition):</strong>\n<ul class=\"fig-list\"><li>Karosserie- und Komfortelektronik (Lieferant für Karosseriezustände, Tür-/Klappenstatus, Bedienerschnittstellen für Niveauwahl).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Bus-Topologie &amp; Port-Verbindungen</h5>\n<ul class=\"fig-list\"><li><strong>VFB-Interconnect:</strong> Horizontale Leitungsstränge repräsentieren den logischen <em>Virtual Functional Bus</em> (VFB).\n</li><li><strong>Konnektoren:</strong>\n<ul class=\"fig-list\"><li><em>Assembly Connectors</em> (<code>AssemblySwConnector</code>): Verbinden Ports gleichrangiger SW-Cs innerhalb der Domänen bzw. über Domänengrenzen hinweg.\n</li><li><em>Delegation Connectors</em> (<code>DelegationSwConnector</code>): Führen interne Ports der Sub-Komposition <code>Active Suspension</code> über Kompositionsgrenzen an den VFB-Bus der übergeordneten Domäne <code>Chassis</code>.\n</li></ul>\n</li><li><strong>Interface-Typen:</strong> Überwiegend <code>SenderReceiverInterface</code> (periodische Zustandsgrößen, Soll-/Ist-Kräfte, Höhenstände) sowie <code>ClientServerInterface</code> (Zustandsumschaltung, Funktionsfreigaben, Kalibrierung).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Triggerung &amp; Task-Scheduling:</strong>\n<ul class=\"fig-list\"><li>Periodische Ausführung über RTE-Events (<code>TimingEvent</code>):\n<ul class=\"fig-list\"><li>Stabilitätskritische Regelschleifen (<code>ESC</code>, <code>RSC</code>, <code>Active Stabilizer</code>, <code>Full Active Suspension</code>): Typische Abtastzeiten von <strong>5 ms bis 10 ms</strong>.\n</li><li>Niveau- und Komfortregelung (<code>Body Level Actuator</code>, <code>Switchable Spring</code>): Typische Abtastzeiten von <strong>20 ms bis 100 ms</strong>.\n</li></ul>\n</li></ul>\n</li><li><strong>Datenfluss &amp; Regelkreis:</strong>\n<ol class=\"fig-list\"><li><em>Eingangsgrößen:</em> Rechnerische Erfassung von Raddrehzahlen, Lenkwinkel, Gierrate, Quer-/Längsbeschleunigung und Federwegen/Höhenständen über Sensor-SW-Cs.\n</li><li><em>Koordination:</em> <code>ESC</code> und <code>RSC</code> ermitteln fahrdynamische Momentenbedarfe; Koordination mit dem <code>Power Train Coordinator</code> zur Begrenzung/Erhöhung des Antriebsmoments via VFB.\n</li><li><em>Aktuator-Sollwertgenerierung:</em> <code>Active Suspension</code> transformiert Wank-, Nick- und Hubanforderungen in rad- bzw. achsspezifische Sollwerte für Dämpfer-, Feder-, Stabilisator- und Sturzaktoren.\n</li><li><em>Ausgangsgrößen:</em> Übertragung an Aktuator-SW-Cs oder unterlagerte Leistungstreiber.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Plausibilisierungsfehler (z. B. Sensor-Ausfall, Signal-Ungültigkeiten <code>INVALID</code>): Asynchrone Fehlermeldung an den Diagnostic Event Manager (<code>Dem_SetEventStatus</code>).\n</li><li>Rückfallebenen: Bei Teilausfall Umschaltung der adaptiven/aktiven Aktuatoren in den fail-safe passiven Zustand (z. B. Dämpfer auf Default-Kennlinie).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierte Applikationsschnittstellen (AUTOSAR AI):</strong>\n<ul class=\"fig-list\"><li>Die in <code>AUTOSAR_ApplicationInterfaces_Explanation_Chassis</code> spezifizierten Komponenten erfordern zwingend die Einhaltung der standardisierten Datentypen, Einheiten (SI-Basiseinheiten wie m, m/s^2, rad/s, N, Nm), Skalierungen und Invalid-Werte gemäß den entsprechenden <code>PortInterface</code>-Definitionen.\n</li></ul>\n</li><li><strong>Topologie- und ECU-Allokation:</strong>\n<ul class=\"fig-list\"><li>Die gezeigte VFB-Struktur ist hardware-agnostisch. Die SW-Cs können auf einem zentralen Domain-Controller (Chassis/Fahrwerk-ECU) konsolidiert oder über mehrere vernetzte Steuergeräte (z. B. ESC-Steuergerät, Dämpfer-ECUs via CAN/FlexRay/Ethernet) verteilt werden.\n</li><li>Bei verteilter Allokation mappt der Systemintegrator die VFB-Verbindungen auf Signal-Frames im COM-Stack (<code>ComSignal</code>, <code>PDU</code>).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen (Embedded):</strong>\n<ul class=\"fig-list\"><li>Aktive Dämpfer- und Krafteinprägungssysteme (<code>Full Active Suspension</code>, <code>Semi-active Damper</code>) weisen extrem enge Latenztoleranzen auf.\n</li><li>Falls die standardmäßige RTE-Kommunikation bei hochfrequenten PWM-/SPI-Treiberansteuerungen zu hohe Laufzeit-Overheads erzeugt, erfolgt die unterlagerte Aktuatoranbindung normativ über ein <em>Complex Device Driver</em> (CDD) unter Umgehung des Standard-I/O-Stacks.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-7ec975129ec8f170", "to": "FIG-9251c4ccddafefc8", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>Chassis</code>: Domänenbeschriftung im übergeordneten Container ergänzt (in der Vorlage unbeschriftet).\n</li><li><code>Active Suspension</code>: Bezeichner des Sub-Kompositions-Containers ergänzt.\n</li><li><code>Electronic Stability Control (ESC)</code>: Komponentenbeschriftung im linken oberen Block ergänzt.\n</li><li><code>Roll Stability Control (RSC)</code>: Komponentenbeschriftung im mittleren oberen Block ergänzt.\n</li><li><code>Power Train</code>: Domänenbeschriftung im oberen rechten Container ergänzt.\n</li><li><code>Power Train Coordinator</code>: Komponentenbeschriftung im Block innerhalb von <code>Power Train</code> ergänzt.\n</li><li><code>Body</code>: Domänenbeschriftung im unteren rechten Container ergänzt.\n</li><li><code>Semi-active Damper</code>, <code>Switchable Damper</code>, <code>Active Stabilizer</code>, <code>Switchable Spring</code>, <code>Body Level Actuator</code>, <code>Full Active Suspension</code>, <code>Active Camber</code>: Komponentenbeschriftungen aller Blöcke innerhalb der Sub-Komposition <code>Active Suspension</code> ergänzt.\n</li></ul>"}]};
